ROOT=pathlib.Path(__file__).resolve().parents[1];STAMP='2026-10-17-midi-page-leds-test-2'
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();cross=next(c for c in ('m68k-linux-gnu-','m68k-elf-') if shutil.which(c+'gcc'))
 with tempfile.TemporaryDirectory() as temp:
  d=pathlib.Path(temp);subprocess.run([cross+'gcc','-mcpu=54418','-Os','-ffreestanding','-fno-builtin','-fno-pic','-fno-common','-fno-stack-protector','-fno-asynchronous-unwind-tables','-c',str(ROOT/'tools/machines/midi_lanes/page_leds.c'),'-o',str(d/'x.o')],check=True);(d/'x.ld').write_text('SECTIONS { .text 0 : { *(.text*) *(.rodata*) } . = ALIGN(4); .data : { *(.data*) } . = ALIGN(4); .bss : { *(.bss*) *(COMMON) } . = ALIGN(4); pg_end = .; }');subprocess.run([cross+'ld','--emit-relocs','-T',str(d/'x.ld'),'-o',str(d/'x.elf'),str(d/'x.o')],check=True);subprocess.run([cross+'objcopy','-O','binary',str(d/'x.elf'),str(d/'x.bin')],check=True);sy=symbols(cross,d/'x.elf');raw=(d/'x.bin').read_bytes();raw+=bytes(sy['pg_end']-len(raw));rel=subprocess.check_output([cross+'readelf','-rW',str(d/'x.elf')],text=True);offsets=[int(m.group(1),16) for m in re.finditer(r'^([0-9a-f]+)\s+\S+\s+R_68K_32\b',rel,re.M)];assert all(int.from_bytes(raw[i:i+4],'big')<len(raw) for i in offsets);data=dict(hex=raw.hex(),symbols=sy,reloc=offsets)
